#!/usr/bin/env bash
# Pre-build a bootable disk image for a tree, ONCE, on SSD under the research
# folder (not per-run, not in /tmp). Holds the kernel Image + initramfs; the tiny
# boot.scr is (re)generated by run-qemu at launch with the run's bootargs, so
# --kaslr/console flow through in firmware mode (u-boot ignores QEMU -append).
#
# usage: build-bootdisk.sh <tree-dir>
# output: <tree-dir>/boot/uboot.img  (MBR + FAT: /Image, /rootfs.cpio.gz)
# rebuild only when Image or rootfs is newer than the disk.
set -uo pipefail
tree="${1:?usage: build-bootdisk.sh <tree-dir>}"
[ -d "$tree" ] || { echo "no such tree: $tree" >&2; exit 1; }
[ -f "$tree/tree.conf" ] || { echo "not a tree (no tree.conf): $tree" >&2; exit 1; }

# One grammar, shared with kbuildlab and the editor adapter: KEY, optional
# spaces, '=', optional spaces, value; trailing comment and space stripped, one
# layer of surrounding double quotes removed.
get() {
    sed -n "s/^[[:space:]]*$1[[:space:]]*=[[:space:]]*//p" "$tree/tree.conf" \
        | head -1 | sed 's/#.*//; s/[[:space:]]*$//; s/^"//; s/"$//'
}

# The kernel source directory, by the same rule kbuildlab uses: SRC_DIR when the
# tree states one, else the single directory that IS a kernel source (a top-level
# Makefile carrying VERSION/PATCHLEVEL/SUBLEVEL, plus arch/ and Kbuild).  Assuming
# "kernel" is wrong for any tree that renamed its clone, and the failure is a
# boot disk quietly built from a stale image somewhere else.
_is_ksrc() {
    [ -d "$1/arch" ] && [ -f "$1/Kbuild" ] && [ -f "$1/Makefile" ] &&
    grep -qE '^[[:space:]]*VERSION[[:space:]]*=' "$1/Makefile" 2>/dev/null &&
    grep -qE '^[[:space:]]*PATCHLEVEL[[:space:]]*=' "$1/Makefile" 2>/dev/null
}
src="$(get SRC_DIR)"
if [ -n "$src" ]; then src="$tree/$src"; else
    src=""; n=0
    for d in "$tree"/*/; do d="${d%/}"; _is_ksrc "$d" && { src="$d"; n=$((n+1)); }; done
    [ "$n" -eq 1 ] || src="$tree/kernel"
fi
[ -d "$src" ] || { echo "no kernel source in $tree (looked for SRC_DIR, then by content)" >&2; exit 1; }

image_rel="$(get KERNEL_IMAGE_REL)"; image="$src/$image_rel"
initrd_rel="$(get INITRD)"; initrd="$tree/$initrd_rel"
[ -f "$image" ]  || { echo "no kernel image: $image (build it first)"; exit 1; }
[ -f "$initrd" ] || { echo "no initrd: $initrd (build the rootfs first)"; exit 1; }

out="$tree/boot"; mkdir -p "$out"; disk="$out/uboot.img"
# Up to date means the payloads are IN there and current, not merely that the
# image file is newer.  Every one of these disks was found holding a formatted
# but EMPTY filesystem -- 261 non-zero bytes in 92 MB -- while the mtime guard
# reported all of them up to date, because an mtime says when the file was
# written and nothing about what is in it.  The miss had no symptom: run-qemu
# copies the current kernel into its own /dev/shm copy on every boot, so the
# guest booted correctly from a disk that could not have booted it alone.
_has_payload() {
    mdir -i "$disk@@1M" ::/Image >/dev/null 2>&1 &&
    { [ ! -f "$initrd" ] || mdir -i "$disk@@1M" ::/rootfs.cpio.gz >/dev/null 2>&1; }
}
if [ -f "$disk" ] && [ "$disk" -nt "$image" ] && [ "$disk" -nt "$initrd" ] && _has_payload; then
    echo "up to date: $disk"; exit 0
fi

# size = Image + initrd + 32MiB slack, rounded up to MiB
sz=$(( ( $(stat -c%s "$image") + $(stat -c%s "$initrd") ) / 1048576 + 40 ))
echo "building $disk (${sz}MiB): $(basename "$image") + $(basename "$initrd")"
rm -f "$disk"
dd if=/dev/zero of="$disk" bs=1M count="$sz" status=none
printf 'label: dos\nstart=2048, type=0c, bootable\n' | sfdisk "$disk" >/dev/null 2>&1
mformat -i "$disk@@1M" -v KBLBOOT ::
mcopy -i "$disk@@1M" "$image"  ::/Image
mcopy -i "$disk@@1M" "$initrd" ::/rootfs.cpio.gz
echo "done: $disk"
